insert into questions (type,difficulty,"questionText","choiceA","choiceB","choiceC","choiceD","correctAnswer","explanationHe",tags,"estimatedTimeSec","cefrLevel",status,"isPilot") values ('restatement',7,'Researchers postponed their recommendation because the available data were too limited to support a firm conclusion in public institutions, as described in a policy review.','The researchers postponed collecting data after reaching a firm conclusion.','The available data forced the researchers to reject all conclusions.','The researchers delayed giving advice since the evidence was insufficient for a definite conclusion.','The researchers made a recommendation because the data were complete.','C','התשובה הנכונה שומרת על משמעות המשפט המקורי בלי להוסיף או לסתור מידע.','["simulation_28", "restatement", "practice_pool"]'::jsonb,70,'C1','approved',false);
insert into questions (type,difficulty,"questionText","choiceA","choiceB","choiceC","choiceD","correctAnswer","explanationHe",tags,"estimatedTimeSec","cefrLevel",status,"isPilot") values ('restatement',7,'The author suggests that frequent practice is effective only when learners receive feedback on their mistakes during periods of change, as described in a classroom discussion.','The author believes mistakes should be ignored during practice.','The author claims feedback is useful only when students stop practicing.','The author suggests that practice and feedback are unrelated.','The author believes practice works best if learners are told what they did wrong.','D','התשובה הנכונה שומרת על משמעות המשפט המקורי בלי להוסיף או לסתור מידע.','["simulation_28", "restatement", "practice_pool"]'::jsonb,70,'C1','approved',false);
insert into questions (type,difficulty,"questionText","choiceA","choiceB","choiceC","choiceD","correctAnswer","explanationHe",tags,"estimatedTimeSec","cefrLevel",status,"isPilot") values ('restatement',7,'The new system was adopted not because it was cheaper, but because it made the process more transparent in small communities, as described in a research summary.','The main reason for adopting the new system was improved transparency rather than lower cost.','The new system was rejected because it was not transparent.','The new system was adopted mainly because it reduced costs.','The process became less transparent after the new system was adopted.','A','התשובה הנכונה שומרת על משמעות המשפט המקורי בלי להוסיף או לסתור מידע.','["simulation_28", "restatement", "practice_pool"]'::jsonb,70,'C1','approved',false);
insert into questions (type,difficulty,"questionText","choiceA","choiceB","choiceC","choiceD","correctAnswer","explanationHe",tags,"estimatedTimeSec","cefrLevel",status,"isPilot") values ('restatement',7,'Even though the experiment was small, its results raised important questions for future research when resources are limited, as described in a public debate.','Future research became unnecessary after the experiment.','Despite its limited size, the experiment produced results that future studies should examine.','The experiment was too large to raise useful questions.','The results were ignored because the experiment was not small.','B','התשובה הנכונה שומרת על משמעות המשפט המקורי בלי להוסיף או לסתור מידע.','["simulation_28", "restatement", "practice_pool"]'::jsonb,70,'C1','approved',false);
insert into questions (type,difficulty,"questionText","choiceA","choiceB","choiceC","choiceD","correctAnswer","explanationHe",tags,"estimatedTimeSec","cefrLevel",status,"isPilot") values ('restatement',7,'The passage implies that convenience may encourage people to use a service, but it does not guarantee satisfaction under careful supervision, as described in a training program.','The passage denies that convenience affects service use.','The passage says convenience always guarantees satisfaction.','The passage suggests that a convenient service can attract users without necessarily satisfying them.','The passage argues that inconvenient services attract the most users.','C','התשובה הנכונה שומרת על משמעות המשפט המקורי בלי להוסיף או לסתור מידע.','["simulation_28", "restatement", "practice_pool"]'::jsonb,70,'C1','approved',false);
insert into questions (type,difficulty,"questionText","choiceA","choiceB","choiceC","choiceD","correctAnswer","explanationHe",tags,"estimatedTimeSec","cefrLevel",status,"isPilot") values ('restatement',7,'The committee approved the plan only after several risks had been identified and addressed after initial trials, as described in an evaluation report.','The committee rejected the plan because all risks were addressed.','The plan was accepted although no risks were identified.','The committee approved the plan before considering any risks.','The plan was accepted once the committee had dealt with the risks it found.','D','התשובה הנכונה שומרת על משמעות המשפט המקורי בלי להוסיף או לסתור מידע.','["simulation_28", "restatement", "practice_pool"]'::jsonb,70,'C1','approved',false);
insert into questions (type,difficulty,"questionText","choiceA","choiceB","choiceC","choiceD","correctAnswer","explanationHe",tags,"estimatedTimeSec","cefrLevel",status,"isPilot") values ('restatement',6,'The writer contrasts short-term popularity with long-term reliability when resources are limited, as described in a pilot study in a coastal student forum context.','The writer points out a difference between being popular now and being dependable over time.','The writer says popularity and reliability are exactly the same.','The writer argues that long-term reliability is impossible.','The writer discusses reliability without mentioning popularity.','A','התשובה הנכונה שומרת על משמעות המשפט המקורי בלי להוסיף או לסתור מידע.','["simulation_29", "restatement", "practice_pool"]'::jsonb,70,'B2','approved',false);
insert into questions (type,difficulty,"questionText","choiceA","choiceB","choiceC","choiceD","correctAnswer","explanationHe",tags,"estimatedTimeSec","cefrLevel",status,"isPilot") values ('restatement',6,'Although exam simulations was initially criticized, later evidence showed that it could be useful when applied carefully under careful supervision, as described in a professional workshop.','Early criticism proved that exam simulations had no value at all.','Later evidence suggested that exam simulations, despite early criticism, may have value if used carefully.','The usefulness of exam simulations was accepted before anyone criticized it.','Later evidence showed that exam simulations should never be applied.','B','התשובה הנכונה שומרת על משמעות המשפט המקורי בלי להוסיף או לסתור מידע.','["simulation_29", "restatement", "practice_pool"]'::jsonb,70,'B2','approved',false);
