insert into questions (type,difficulty,"questionText","choiceA","choiceB","choiceC","choiceD","correctAnswer","explanationHe",tags,"estimatedTimeSec","cefrLevel",status,"isPilot") values ('restatement',6,'The writer contrasts short-term popularity with long-term reliability after initial trials, as described in a professional workshop in a introductory education panel context.','The writer says popularity and reliability are exactly the same.','The writer points out a difference between being popular now and being dependable over time.','The writer argues that long-term reliability is impossible.','The writer discusses reliability without mentioning popularity.','B','התשובה הנכונה שומרת על משמעות המשפט המקורי בלי להוסיף או לסתור מידע.','["simulation_30", "restatement", "practice_pool"]'::jsonb,70,'B2','approved',false);
insert into questions (type,difficulty,"questionText","choiceA","choiceB","choiceC","choiceD","correctAnswer","explanationHe",tags,"estimatedTimeSec","cefrLevel",status,"isPilot") values ('restatement',6,'Although online tutoring was initially criticized, later evidence showed that it could be useful when applied carefully in schools, as described in a policy review.','Early criticism proved that online tutoring had no value at all.','The usefulness of online tutoring was accepted before anyone criticized it.','Later evidence suggested that online tutoring, despite early criticism, may have value if used carefully.','Later evidence showed that online tutoring should never be applied.','C','התשובה הנכונה שומרת על משמעות המשפט המקורי בלי להוסיף או לסתור מידע.','["simulation_30", "restatement", "practice_pool"]'::jsonb,70,'B2','approved',false);
insert into questions (type,difficulty,"questionText","choiceA","choiceB","choiceC","choiceD","correctAnswer","explanationHe",tags,"estimatedTimeSec","cefrLevel",status,"isPilot") values ('restatement',6,'The report does not claim that digital note-taking solves every problem; it argues only that it can reduce one specific difficulty for adult learners, as described in a classroom discussion.','The report discusses many solutions but never mentions a specific problem.','The report rejects the idea that digital note-taking can help in any way.','The report argues that digital note-taking solves all problems completely.','According to the report, digital note-taking is not a complete solution but may help with a particular problem.','D','התשובה הנכונה שומרת על משמעות המשפט המקורי בלי להוסיף או לסתור מידע.','["simulation_30", "restatement", "practice_pool"]'::jsonb,70,'B2','approved',false);
insert into questions (type,difficulty,"questionText","choiceA","choiceB","choiceC","choiceD","correctAnswer","explanationHe",tags,"estimatedTimeSec","cefrLevel",status,"isPilot") values ('restatement',6,'Researchers postponed their recommendation because the available data were too limited to support a firm conclusion in public institutions, as described in a research summary.','The researchers delayed giving advice since the evidence was insufficient for a definite conclusion.','The researchers made a recommendation because the data were complete.','The available data forced the researchers to reject all conclusions.','The researchers postponed collecting data after reaching a firm conclusion.','A','התשובה הנכונה שומרת על משמעות המשפט המקורי בלי להוסיף או לסתור מידע.','["simulation_30", "restatement", "practice_pool"]'::jsonb,70,'B2','approved',false);
insert into questions (type,difficulty,"questionText","choiceA","choiceB","choiceC","choiceD","correctAnswer","explanationHe",tags,"estimatedTimeSec","cefrLevel",status,"isPilot") values ('restatement',6,'The author suggests that frequent practice is effective only when learners receive feedback on their mistakes during periods of change, as described in a public debate.','The author suggests that practice and feedback are unrelated.','The author believes practice works best if learners are told what they did wrong.','The author claims feedback is useful only when students stop practicing.','The author believes mistakes should be ignored during practice.','B','התשובה הנכונה שומרת על משמעות המשפט המקורי בלי להוסיף או לסתור מידע.','["simulation_30", "restatement", "practice_pool"]'::jsonb,70,'B2','approved',false);
insert into questions (type,difficulty,"questionText","choiceA","choiceB","choiceC","choiceD","correctAnswer","explanationHe",tags,"estimatedTimeSec","cefrLevel",status,"isPilot") values ('restatement',7,'The new system was adopted not because it was cheaper, but because it made the process more transparent in small communities, as described in a training program.','The new system was adopted mainly because it reduced costs.','The process became less transparent after the new system was adopted.','The main reason for adopting the new system was improved transparency rather than lower cost.','The new system was rejected because it was not transparent.','C','התשובה הנכונה שומרת על משמעות המשפט המקורי בלי להוסיף או לסתור מידע.','["simulation_30", "restatement", "practice_pool"]'::jsonb,70,'C1','approved',false);
