insert into questions (type,difficulty,"questionText","choiceA","choiceB","choiceC","choiceD","correctAnswer","explanationHe",tags,"estimatedTimeSec","cefrLevel",status,"isPilot") values ('restatement',7,'The committee approved the plan only after several risks had been identified and addressed after initial trials, as described in a policy review in a central training course context.','The plan was accepted although no risks were identified.','The committee approved the plan before considering any risks.','The plan was accepted once the committee had dealt with the risks it found.','The committee rejected the plan because all risks were addressed.','C','התשובה הנכונה שומרת על משמעות המשפט המקורי בלי להוסיף או לסתור מידע.','["simulation_33", "restatement", "practice_pool"]'::jsonb,70,'C1','approved',false);
insert into questions (type,difficulty,"questionText","choiceA","choiceB","choiceC","choiceD","correctAnswer","explanationHe",tags,"estimatedTimeSec","cefrLevel",status,"isPilot") values ('restatement',6,'The decline in complaints was gradual, so managers were careful not to attribute it to a single change in schools, as described in a classroom discussion in a online training course context.','Managers ignored the decline because it was caused by one change.','Managers blamed a single change because complaints rose quickly.','The decline in complaints was sudden and easy to explain.','Because complaints decreased slowly, managers avoided saying that one change alone caused the improvement.','D','התשובה הנכונה שומרת על משמעות המשפט המקורי בלי להוסיף או לסתור מידע.','["simulation_33", "restatement", "practice_pool"]'::jsonb,70,'B2','approved',false);
insert into questions (type,difficulty,"questionText","choiceA","choiceB","choiceC","choiceD","correctAnswer","explanationHe",tags,"estimatedTimeSec","cefrLevel",status,"isPilot") values ('restatement',6,'The writer contrasts short-term popularity with long-term reliability for adult learners, as described in a research summary in a evening training course context.','The writer points out a difference between being popular now and being dependable over time.','The writer says popularity and reliability are exactly the same.','The writer argues that long-term reliability is impossible.','The writer discusses reliability without mentioning popularity.','A','התשובה הנכונה שומרת על משמעות המשפט המקורי בלי להוסיף או לסתור מידע.','["simulation_33", "restatement", "practice_pool"]'::jsonb,70,'B2','approved',false);
insert into questions (type,difficulty,"questionText","choiceA","choiceB","choiceC","choiceD","correctAnswer","explanationHe",tags,"estimatedTimeSec","cefrLevel",status,"isPilot") values ('restatement',6,'Although digital note-taking was initially criticized, later evidence showed that it could be useful when applied carefully in public institutions, as described in a public debate in a summer training course context.','Later evidence showed that digital note-taking should never be applied.','Later evidence suggested that digital note-taking, despite early criticism, may have value if used carefully.','The usefulness of digital note-taking was accepted before anyone criticized it.','Early criticism proved that digital note-taking had no value at all.','B','התשובה הנכונה שומרת על משמעות המשפט המקורי בלי להוסיף או לסתור מידע.','["simulation_33", "restatement", "practice_pool"]'::jsonb,70,'B2','approved',false);
insert into questions (type,difficulty,"questionText","choiceA","choiceB","choiceC","choiceD","correctAnswer","explanationHe",tags,"estimatedTimeSec","cefrLevel",status,"isPilot") values ('restatement',6,'The report does not claim that remote medical advice solves every problem; it argues only that it can reduce one specific difficulty during periods of change, as described in a training program in a advanced training course context.','The report discusses many solutions but never mentions a specific problem.','The report rejects the idea that remote medical advice can help in any way.','According to the report, remote medical advice is not a complete solution but may help with a particular problem.','The report argues that remote medical advice solves all problems completely.','C','התשובה הנכונה שומרת על משמעות המשפט המקורי בלי להוסיף או לסתור מידע.','["simulation_33", "restatement", "practice_pool"]'::jsonb,70,'B2','approved',false);
insert into questions (type,difficulty,"questionText","choiceA","choiceB","choiceC","choiceD","correctAnswer","explanationHe",tags,"estimatedTimeSec","cefrLevel",status,"isPilot") values ('restatement',7,'Researchers postponed their recommendation because the available data were too limited to support a firm conclusion in small communities, as described in an evaluation report in a introductory training course context.','The researchers made a recommendation because the data were complete.','The researchers postponed collecting data after reaching a firm conclusion.','The available data forced the researchers to reject all conclusions.','The researchers delayed giving advice since the evidence was insufficient for a definite conclusion.','D','התשובה הנכונה שומרת על משמעות המשפט המקורי בלי להוסיף או לסתור מידע.','["simulation_33", "restatement", "practice_pool"]'::jsonb,70,'C1','approved',false);
